// Validate PORT environment variable
function validatePort() {
  const port = process.env.PORT;
  if (!port) {
    console.log('✓ PORT: Not set (using default 3000)');
    return true;
  }

  const portNum = parseInt(port);
  if (isNaN(portNum) || portNum < 1 || portNum > 65535) {
    console.log('✗ PORT: Invalid port number');
    return false;
  }

  console.log('✓ PORT: Valid:', port);
  return true;
}

// Validate database URL
function validateDatabaseURL() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('✗ DATABASE_URL: Not set');
    return false;
  }

  // Check if URL has required components
  try {
    const urlObj = new URL(dbUrl);

    // Verify URL has required components
    if (!urlObj.protocol || !urlObj.hostname) {
      console.log('✗ DATABASE_URL: Invalid format');
      return false;
    }

    // Check if it's a PostgreSQL URL
    if (!urlObj.protocol.startsWith('postgres')) {
      console.log('✗ DATABASE_URL: Not a PostgreSQL URL');
      return false;
    }

    // Check for credentials in URL
    if (!urlObj.username || !urlObj.password) {
      console.log('✗ DATABASE_URL: Missing credentials');
      return false;
    }

    // Redact sensitive information in output
    const redactedUrl = dbUrl
      .replace(/:([^:@]+)@/, ':****@')
      .replace(/\/([^:@/]+)/, '/****');

    console.log('✓ DATABASE_URL: Format valid:', redactedUrl);
    return true;
  } catch (error) {
    console.log('✗ DATABASE_URL: Invalid URL format');
    return false;
  }
}

