// Script to verify the validity of credentials in the environment
// Note: In a real scenario, credential verification should be done through
// proper secret management systems and not hardcoded in scripts

const https = require('https');
const url = require('url');
const { Client } = require('pg');

// Extract database credentials from the DATABASE_URL
function parseDatabaseUrl(dbUrl) {
  const parsed = url.parse(dbUrl);
  const [, , userPass, hostPortDb] = parsed.href.split('/');
  const [user, password] = userPass.split(':');
  const [host, portWithDb] = hostPortDb.split(':');
  const [port, database] = portWithDb.split('@')[0].split('/');

  return {
    user,
    password,
    host,
    port: port || '5432',
    database
  };
}

// Verify database connection
async function verifyDatabase() {
  console.log('Verifying database connection...');

  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('❌ DATABASE_URL not found in environment');
    return false;
  }

  try {
    const config = parseDatabaseUrl(dbUrl);
    const client = new Client(config);

    await client.connect();
    const result = await client.query('SELECT NOW()');
    console.log(`✅ Database connection successful: ${result.rows[0].now}`);
    await client.end();
    return true;
  } catch (error) {
    console.log(`❌ Database connection failed: ${error.message}`);
    return false;
  }
}

// Generic function to test API keys with HTTPS requests
function testApiKey(endpoint, apiKey, authHeaderName = 'Authorization', apiKeyPrefix = '') {
  return new Promise((resolve) => {
    if (!apiKey) {
      console.log(`❌ ${authHeaderName} not found in environment`);
      resolve(false);
      return;
    }

    const parsedUrl = new URL(endpoint);
    const options = {
      hostname: parsedUrl.hostname,
      port: 443,
      path: parsedUrl.pathname + parsedUrl.search,
      method: 'GET',
      headers: {
        [authHeaderName]: apiKeyPrefix + apiKey
      }
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ ${authHeaderName} test successful - Status: ${res.statusCode}`);
          resolve(true);
        } else {
          console.log(`❌ ${authHeaderName} test failed - Status: ${res.statusCode}`);
          console.log(`Response: ${data.substring(0, 200)}...`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${authHeaderName} test error: ${error.message}`);
      resolve(false);
    });

    req.setTimeout(10000, () => {
      req.destroy();
      console.log(`❌ ${authHeaderName} test timed out`);
      resolve(false);
    });

    req.end();
  });
}

// Verify AWS credentials
async function verifyAWS() {
  console.log('\nVerifying AWS credentials...');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretKey) {
    console.log('❌ AWS credentials not found in environment');
    return false;
  }

  // Test with S3 ListBuckets (a basic AWS service)
  return testApiKey(
    'https://s3.amazonaws.com/', 
    `${accessKeyId}:${secretKey}`,
    'Authorization',
    'AWS '
  );
}

// Verify Anthropic API key
async function verifyAnthropic() {
  console.log('\nVerifying Anthropic API key...');

  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    console.log('❌ ANTHROPIC_API_KEY not found in environment');
    return false;
  }

  return testApiKey(
    'https://api.anthropic.com/v1/complete', 
    apiKey,
    'x-api-key'
  );
}

// Verify Stripe API key
async function verifyStripe() {
  console.log('\nVerifying Stripe API key...');

  const apiKey = process.env.STRIPE_SECRET_KEY;

  if (!apiKey) {
    console.log('❌ STRIPE_SECRET_KEY not found in environment');
    return false;
  }

  return testApiKey(
    'https://api.stripe.com/v1/account', 
    apiKey,
    'Authorization',
    'Bearer '
  );
}

// Verify Logfire token
async function verifyLogfire() {
  console.log('\nVerifying Logfire token...');

  const token = process.env.LOGFIRE_TOKEN;

  if (!token) {
    console.log('❌ LOGFIRE_TOKEN not found in environment');
    return false;
  }

  // Logfire uses the token as a bearer token for authentication
  return testApiKey(
    'https://logfire.pydantic.dev/v1/info', 
    token,
    'Authorization',
    'Bearer '
  );
}

// Verify DREDD_API_KEY
async function verifyDredd() {
  console.log('\nVerifying DREDD_API_KEY...');

  const apiKey = process.env.DREDD_API_KEY;

  if (!apiKey) {
    console.log('❌ DREDD_API_KEY not found in environment');
    return false;
  }

  // Assuming this is a bearer token for some API
  return testApiKey(
    'https://api.example.com/v1/health', // Placeholder - would need to know the actual API
    apiKey,
    'Authorization',
    'Bearer '
  );
}

// Main execution
async function main() {
  console.log('Starting credential verification...\n');

  // Verify all credentials
  const results = {
    database: await verifyDatabase(),
    aws: await verifyAWS(),
    anthropic: await verifyAnthropic(),
    stripe: await verifyStripe(),
    logfire: await verifyLogfire(),
    dred: await verifyDredd()
  };

  console.log('\n--- Summary ---');
  Object.keys(results).forEach(service => {
    console.log(`${service}: ${results[service] ? '✅ VALID' : '❌ INVALID'}`);
  });

  const validCount = Object.values(results).filter(valid => valid).length;
  console.log(`\n${validCount} of ${Object.keys(results).length} credentials are valid`);

  // Exit with error code if any credential is invalid
  if (validCount !== Object.keys(results).length) {
    process.exit(1);
  }
}

main().catch(err => {
  console.error('Unexpected error:', err);
  process.exit(1);
});

