# Security and Error Handling Improvements for app.js

## Critical Issues Addressed

### 1. Input Validation
- Add validation for all incoming requests
- Use express-validator for comprehensive validation
- Validate query parameters, headers, and request bodies

### 2. Error Handling
- Implement proper error handling middleware
- Never expose stack traces to clients
- Log errors appropriately with proper severity levels

### 3. Security Headers
- Implement Helmet.js for security headers
- Set proper Content-Security-Policy
- Enable XSS protection
- Prevent clickjacking with X-Frame-Options

### 4. Rate Limiting
- Protect against brute force and DoS attacks
- Implement per-IP rate limiting
- Configure appropriate request limits

### 5. CORS Configuration
- Explicitly configure CORS instead of allowing all origins
- Only allow required HTTP methods and headers
- Never enable credentials for wildcard origins

### 6. Request Size Limits
- Set reasonable limits on request body size
- Prevent memory denial of service attacks

### 7. Environment Configuration
- Use environment variables for configuration
- Different settings for development, staging, and production

## Implementation Recommendations

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'HEAD'],
  optionsSuccessStatus: 200
};

app.use(cors(corsOptions));

// Request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware for users route
const validateUserRequest = [
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array().map(err => err.msg) 
      });
    }
    next();
  }
];

// Health check with proper error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ 
      status: 'error', 
      message: 'Service unavailable' 
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', validateUserRequest, (req, res) => {
  try {
    // Extract validated query parameters
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    // In a real app, this would query a database with pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination (simplified)
    const startIndex = (page - 1) * limit;
    const paginatedUsers = users.slice(startIndex, startIndex + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        pages: Math.ceil(users.length / limit)
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error' 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  const status = error.status || 500;
  const message = status === 500 ? 'Internal server error' : error.message;

  res.status(status).json({
    error: message
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;
```

## Additional Security Recommendations

1. **Environment Variables**: Use a `.env` file for configuration
2. **Logging**: Implement structured logging with winston or pino
3. **Input Sanitization**: Sanitize all user inputs to prevent XSS
4. **Authentication**: Add authentication for protected routes
5. **HTTPS**: Use HTTPS in production with proper certificates
6. **Dependency Updates**: Regularly update dependencies and check for vulnerabilities
7. **Security Testing**: Implement automated security testing in CI/CD pipeline

## Dependencies to Install

```bash
npm install express helmet express-rate-limit cors express-validator
npm install --save-dev dotenv
```

