const pg = require('pg');
const https = require('https');

// Extract database config from URL
function parseDatabaseUrl(url) {
  try {
    const match = url.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):([0-9]+)\/([^\s]+)/);
    if (!match) {
      console.log('❌ Invalid DATABASE_URL format');
      return null;
    }

    return {
      user: match[1],
      password: match[2],
      host: match[3],
      port: match[4],
      database: match[5]
    };
  } catch (error) {
    console.log('❌ Error parsing DATABASE_URL:', error.message);
    return null;
  }
}

// Check database connectivity
async function checkDatabaseConnection() {
  console.log('\n🔍 Checking database connectivity...');

  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.log('⚠️  DATABASE_URL not set in environment');
    return;
  }

  const config = parseDatabaseUrl(databaseUrl);
  if (!config) return;

  // Don't proceed if this looks like a production database
  if (config.database === 'production') {
    console.log('⚠️  Detected production database - skipping connection attempt for safety');
    console.log('   To test production connectivity, use approved monitoring tools');
    return;
  }

  const { Client } = pg;
  const client = new Client(config);

  try {
    await client.connect();
    const result = await client.query('SELECT NOW()');
    console.log(`✅ Database connection successful!`);
    console.log(`   Server time: ${result.rows[0].now}`);
    console.log(`   Connected to: ${config.host}:${config.port}/${config.database}`);
  } catch (error) {
    console.log('❌ Database connection failed:', error.code || error.message);

    // Common error codes with suggestions
    if (error.code === 'ECONNREFUSED') {
      console.log('   → Check if database server is running and accessible');
    } else if (error.code === '28P01') {
      console.log('   → Invalid username or password');
    } else if (error.code === '42501') {
      console.log('   → User lacks permission to access database');
    }
  } finally {
    await client.end().catch(() => {});
  }
}

// Check API key validity
function checkApiKeyValidity() {
  console.log('\n🔍 Checking API key patterns...');

  // Check Anthropic API key
  const anthropicKey = process.env.ANTHROPIC_API_KEY;
