    console.log('❌ STRIPE_SECRET_KEY: Invalid format (should start with sk_live_ or sk_test_)');
  } else {
    console.log('✅ STRIPE_SECRET_KEY: Format appears valid');
  }

  // Check AWS key
  const awsKey = process.env.AWS_ACCESS_KEY_ID;
  if (!awsKey) {
    console.log('⚠️  AWS_ACCESS_KEY_ID not set');
  } else if (!awsKey.startsWith('AKIA')) {
    console.log('❌ AWS_ACCESS_KEY_ID: Invalid format (should start with AKIA)');
  } else {
    console.log('✅ AWS_ACCESS_KEY_ID: Format appears valid');
  }
}

// Main execution
async function main() {
  console.log('🔐 Security Diagnostic Tool');
  console.log('========================');

  // Only check API key formats by default for safety
  checkApiKeyValidity();

  // Only attempt database connection if explicitly requested
