  if (process.argv.includes('--connect') || process.argv.includes('-c')) {
    await checkDatabaseConnection();
  } else {
    console.log('\n💡 To test database connectivity, run with: node diagnostic.js --connect');
    console.log('   WARNING: Only do this in approved environments with proper permissions');
  }

  console.log('\n📋 Environment check complete\n');
}

// Run if called directly
if (require.main === module) {
  main().catch(console.error);
}

module.exports = { parseDatabaseUrl, checkDatabaseConnection, checkApiKeyValidity };

