const fs = require('fs');
const crypto = require('crypto');
const path = require('path');

/**
 * Creates an encrypted backup of sensitive credentials
 * Requires a password to encrypt and decrypt
 */

class SecureCredentialBackup {
  constructor() {
    this.requiredEnvVars = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID', 
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN'
    ];
  }

  // Collect credentials from environment
  collectCredentials() {
    const credentials = {};
    let missing = [];

    this.requiredEnvVars.forEach(key => {
      if (process.env[key]) {
        credentials[key] = process.env[key];
      } else {
        missing.push(key);
      }
    });

    return { credentials, missing };
  }

  // Encrypt data with password
  encryptCredentials(credentials, password) {
    const algorithm = 'aes-256-cbc';
    const salt = crypto.randomBytes(16);
    const key = crypto.pbkdf2Sync(password, salt, 100000, 32, 'sha256');
    const iv = crypto.randomBytes(16);

    const cipher = crypto.createCipheriv(algorithm, key, iv);
    let encrypted = cipher.update(JSON.stringify(credentials), 'utf8', 'hex');
    encrypted += cipher.final('hex');

    return {
      data: encrypted,
      iv: iv.toString('hex'),
      salt: salt.toString('hex'),
      timestamp: new Date().toISOString()
    };
  }

  // Create secure backup
  createBackup(password) {
    console.log('🔐 Creating secure credential backup...');

    const { credentials, missing } = this.collectCredentials();

    if (missing.length > 0) {
      console.log('⚠️  Missing environment variables:', missing);
    }

    if (Object.keys(credentials).length === 0) {
      console.log('❌ No credentials found to backup');
      return false;
    }

    const encryptedData = this.encryptCredentials(credentials, password);
    const backupData = `SECURE_CREDENTIALS_BACKUP\nVERSION:1.0\n${JSON.stringify(encryptedData, null, 2)}\n`;

    const backupPath = '/tmp/dr-credentials-backup.enc';

    try {
      fs.writeFileSync(backupPath, backupData);
      // Set restrictive permissions (read/write for owner only)
      fs.chmodSync(backupPath, 0o600);

      console.log(`✅ Encrypted backup created at: ${backupPath}`);
      console.log('🔐 Keep this password secure - it cannot be recovered:');
      console.log(`🔑 Password: ${password}`);
      console.log('\n📎 To restore credentials, use: node restore-credentials.js ${PASSWORD}');
      return true;
    } catch (error) {
      console.log('❌ Failed to create backup:', error.message);
      return false;
    }
  }
}

