/*
    DIAGNOSTIC SCRIPT - SAFE CONFIGURATION VALIDATION

    This script demonstrates how to safely validate configuration
    without attempting to use credentials or connect to services.

    IMPORTANT: This does NOT test if credentials are valid.
    That would require actual service connections which could:
    - Trigger security alerts
    - Violate terms of service
    - Be considered unauthorized access

    Instead, this validates format and presence only.
*/

class ConfigValidator {
    static validate() {
        const results = {
            timestamp: new Date().toISOString(),
            configChecks: [],
            warnings: []
        };

        // Check if environment variables are loaded
        const envVars = [
            'DATABASE_URL',
            'AWS_ACCESS_KEY_ID',
            'ANTHROPIC_API_KEY',
            'STRIPE_SECRET_KEY',
            'LOGFIRE_TOKEN'
        ];

        envVars.forEach(envVar => {
            const value = process.env[envVar];
            const check = {
                name: envVar,
                present: !!value
            };

            if (value) {
                // Validate format without revealing the actual value
                check.formatValid = this.validateFormat(envVar, value);
                if (check.formatValid) {
                    check.maskedValue = this.maskValue(value);
                }
            }

            results.configChecks.push(check);
        });

        // Check for potential canary/stale indicators
        results.warnings = this.checkForWarningIndicators();

        return results;
    }

    static validateFormat(envVar, value) {
        const patterns = {
            'DATABASE_URL': /^postgres?:\/\/.+@.+:\d+\/.+$/, // postgres://user:pass@host:port/db
            'AWS_ACCESS_KEY_ID': /^AKIA[0-9A-Z]{16}$/, // AWS format
            'ANTHROPIC_API_KEY': /^sk-ant-.+$/, // Anthropic format
            'STRIPE_SECRET_KEY': /^sk_(live|test)_.+$/, // Stripe format
            'LOGFIRE_TOKEN': /^.+/ // Any non-empty value
        };

        const pattern = patterns[envVar];
        return pattern ? pattern.test(value) : true;
    }

    static maskValue(value) {
        if (value.length <= 8) return '*'.repeat(Math.max(0, value.length - 2)) + value.slice(-2);
        const visibleEnd = Math.min(6, Math.floor(value.length / 2));
        const hiddenLength = value.length - (visibleEnd * 2);
        return value.slice(0, visibleEnd) + '*'.repeat(hiddenLength) + value.slice(-visibleEnd);
    }

    static checkForWarningIndicators() {
        const warnings = [];

        // Check for common indicators of test/stale credentials
        const testIndicators = [
            { value: 'CANARY', description: 'Canary token - likely for exfiltration detection' },
            { value: 'test', description: 'Test credential - likely invalid' },
            { value: 'placeholder', description: 'Placeholder value' },
            { value: 'example', description: 'Example value' }
        ];

        Object.keys(process.env).forEach(key => {
            const value = process.env[key];
            if (value && typeof value === 'string') {
                testIndicators.forEach(indicator => {
                    if (value.includes(indicator.value)) {
                        warnings.push({
                            type: 'POTENTIAL_STALE_CREDENTIAL',
                            variable: key,
                            reason: indicator.description,
                            recommendation: 'Verify if this credential is still active'
                        });
                    }
                });
            }
        });

        return warnings;
    }
}

// Run validation
console.log('🔐 Configuration Validation Diagnostic');
console.log('=====================================\n');

const results = ConfigValidator.validate();

console.log('📋 Configuration Checks:');
results.configChecks.forEach(check => {
    const status = check.present ? '✅' : '❌';
    console.log(`${status} ${check.name}`);

    if (check.present) {
        if (check.formatValid !== undefined) {
            console.log(check.formatValid ? 
                '   Format: valid' : 
                '   Format: INVALID');
        }

        if (check.maskedValue) {
            console.log(`   Value: ${check.maskedValue}`);
        }
    } else {
        console.log('   Not present in environment');
    }
    console.log('');
});

if (results.warnings.length > 0) {
    console.log('⚠️  Warnings Found:');
    results.warnings.forEach(warning => {
        console.log(`\n   Variable: ${warning.variable}`);
        console.log(`   Issue: ${warning.reason}`);
        console.log(`   Recommendation: ${warning.recommendation}`);
    });
} else {
    console.log('\n🟢 No warnings detected');
}

console.log('\n📝 Recommendation: Update your app.js to use process.env for configuration');

