const express = require('express');
const app = express();

// Built-in security middleware (replacement for helmet)
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Referrer-Policy', 'no-referrer');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');

  next();
});

// Simple rate limiting using in-memory store
const requestCounts = new Map();
const WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

app.use((req, res, next) => {
  const ip = req.ip;
  const now = Date.now();

  // Clean old entries
  if (requestCounts.size > 1000) {
    // Reset the map if it gets too large
    // In production, you'd want a more sophisticated approach
    for (let [key, value] of requestCounts) {
      if (now - value.timestamp > WINDOW_MS) {
        requestCounts.delete(key);
      }
    }
  }

  const record = requestCounts.get(ip) || { count: 0, timestamp: now };

  // Reset counter if outside the window
  if (now - record.timestamp > WINDOW_MS) {
    record.count = 0;
    record.timestamp = now;
  }

  record.count++;
  requestCounts.set(ip, record);

  if (record.count > MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later.'
    });
  }

  next();
});

// CORS-like middleware (simplified)
app.use((req, res, next) => {
  const allowedOrigin = process.env.ALLOWED_ORIGIN || 'http://localhost:3000';
  res.setHeader('Access-Control-Allow-Origin', allowedOrigin);
  res.setHeader('Access-Control-Allow-Credentials', 'true');
  res.setHeader('Access-Control-Allow-Methods', 'GET,OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

  // Handle preflight requests
  if (req.method === 'OPTIONS') {
    return res.status(200).end();
  }

  next();
});

// Body parsing with size limits
app.use((req, res, next) => {
  let data = '';
  const MAX_SIZE = 10 * 1024; // 10kb

  if (req.method === 'POST' || req.method === 'PUT') {
    req.on('data', chunk => {
      data += chunk;
      if (data.length > MAX_SIZE) {
        res.status(413).json({ error: 'Payload too large' });
        res.end();
      }
    });

    req.on('end', () => {
      if (data) {
        try {
          req.body = JSON.parse(data);
        } catch (e) {
          req.body = {};
        }
      }
      next();
    });

    req.on('error', () => {
      res.status(400).json({ error: 'Invalid request' });
      res.end();
    });
  } else {
    next();
  }
});

// Request logging
app.use((req, res, next) => {
  const start = Date.now();
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - From: ${req.ip}`);

  const originalSend = res.send;
  res.send = function(body) {
    const responseTime = Date.now() - start;
    console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - ${res.statusCode} - ${responseTime}ms`);
    return originalSend.call(this, body);
  };

  next();
});

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters
    const allowedParams = ['detailed', 'format', 'verbose'];
    const invalidParams = Object.keys(req.query)
      .filter(param => !allowedParams.includes(param));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        invalid: invalidParams
      });
    }

    const healthData = {
      status: 'ok',
