    };

    // Enhanced response for detailed requests
    if (req.query.detailed === 'true' || req.query.verbose === 'true') {
      healthData.service = 'user-service';
      healthData.environment = process.env.NODE_ENV || 'development';
      healthData.version = '1.0.0';
    }

    res.json(healthData);
  } catch (error) {
    console.error('Error in /health endpoint:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Users endpoint with comprehensive input validation
app.get('/users', (req, res) => {
  try {
    // Input validation and sanitization
    const page = parseInt(req.query.page) || 1;
    const limit = Math.min(parseInt(req.query.limit) || 10, 100); // Cap at 100
    const sortParam = req.query.sort || 'id';
    const search = req.query.search || '';

    // Validate inputs
    if (page < 1) {
      return res.status(400).json({ 
