const requestCounts = new Map();
const WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

app.use((req, res, next) => {
  const clientIp = req.ip;
  const now = Date.now();

  // Clean old entries
  for (const [ip, data] of requestCounts) {
    if (now - data.windowStart > WINDOW_MS) {
      requestCounts.delete(ip);
    }
  }

  const requestData = requestCounts.get(clientIp) || { count: 0, windowStart: now };

  if (now - requestData.windowStart > WINDOW_MS) {
    requestData.count = 1;
    requestData.windowStart = now;
  } else {
    requestData.count++;
  }

  requestCounts.set(clientIp, requestData);

