const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: false, // Disable CSP for development, enable in production with proper policy
}));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*'
}));

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Parse JSON with size limit
app.use(express.json({
  limit: '10kb'
}));

// Input validation middleware for user ID parameter
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (id !== undefined) {
    const userId = parseInt(id, 10);
    if (isNaN(userId) || userId <= 0) {
      return res.status(400).json({
        error: 'Invalid user ID. ID must be a positive integer.',
        code: 'INVALID_USER_ID'
      });
    }
    req.userId = userId;
  }

  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Health check failed',
      code: 'HEALTH_CHECK_FAILED'
    });
  }
});

// Get all users
app.get('/users', (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Optional: Add query parameter filtering
    const { name } = req.query;
    let filteredUsers = users;

    if (name) {
      if (typeof name !== 'string' || name.length > 50) {
        return res.status(400).json({
          error: 'Invalid name parameter',
          code: 'INVALID_NAME_PARAM'
        });
      }

      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(name.toLowerCase())
      );
    }

    res.json(filteredUsers);
  } catch (error) {
    console.error('Error retrieving users:', error);
    res.status(500).json({
      error: 'Failed to retrieve users',
      code: 'USERS_RETRIEVAL_FAILED'
    });
  }
});

// Get user by ID
app.get('/users/:id', validateUserId, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

