// Middleware to set security headers (basic implementation without helmet)
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Hide powered by express
  res.removeHeader('X-Powered-By');

  // Basic rate limiting (in-memory, not suitable for production with multiple instances)
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Initialize rate limiting store
  if (!app.rateLimitStore) {
    app.rateLimitStore = new Map();
  }

  const client = app.rateLimitStore.get(ip) || { count: 0, firstRequest: now };

  // Reset counter every 15 minutes
  if (now - client.firstRequest > 15 * 60 * 1000) {
    client.count = 0;
    client.firstRequest = now;
  }

  client.count++;
  app.rateLimitStore.set(ip, client);

  // Rate limit: max 100 requests per 15 minutes
  if (client.count > 100) {
    console.warn(`${new Date().toISOString()} - Rate limit exceeded: ${ip} - ${req.method} ${req.url}`);
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later.',
      code: 'RATE_LIMIT_EXCEEDED'
