      path: '/v1/account',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${STRIPE_SECRET_KEY}`
      }
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode === 200) {
          results.stripe = { 
            status: 'VALID', 
            message: 'Stripe API key is valid'
          };
        } else {
          try {
            const response = JSON.parse(data);
            results.stripe = { 
