const express = require('express');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// Security middleware
// Rate limiting to prevent DDoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
});

app.use(limiter);

// Security headers
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  // Use Helmet.js in production for more comprehensive security headers
  next();
});

// Enable CORS with strict origin policy
app.use(cors({
  origin: false // Defaults to reflecting request origin, but can be configured
}));

// Parse JSON with size limits to prevent abuse
app.use(express.json({
  limit: '10kb'
}));

// Validate and sanitize input middleware
const validateIdParam = (req, res, next) => {
  const { id } = req.params;

  // Check if ID parameter exists when expected
  if (id !== undefined) {
    const parsedId = parseInt(id, 10);

    // Validate ID is a positive integer
    if (isNaN(parsedId) || parsedId <= 0) {
      return res.status(400).json({
        error: 'Invalid ID format',
        message: 'ID must be a positive integer'
      });
    }

    // Store validated ID in request object
    req.validated = req.validated || {};
    req.validated.id = parsedId;
  }

  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Service is currently unavailable'
    });
  }
});

