    // If ID is specified, return specific user
    if (req.validated && req.validated.id) {
      const user = mockUsers.find(u => u.id === req.validated.id);
      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          message: `User with ID ${req.validated.id} does not exist`
        });
      }
      return res.json(user);
    }

    // Otherwise return all users
    res.json(mockUsers);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users data'
    });
  }
});

// Generic error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.url} not found`
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
  console.log('Security features enabled: rate limiting, security headers, input validation');
});

module.exports = app;

