const express = require('express');
const app = express();

// Simple rate limiting without external dependencies
const requestRateLimit = new Map();
const WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

app.use((req, res, next) => {
  const clientIP = req.ip || 'unknown';
  const now = Date.now();
  const record = requestRateLimit.get(clientIP) || { count: 0, firstRequest: now };

  // Clean up old records (older than window)
  if (now - record.firstRequest > WINDOW_MS) {
    requestRateLimit.set(clientIP, { count: 1, firstRequest: now });
  } else {
    record.count++;
    requestRateLimit.set(clientIP, record);

    if (record.count > MAX_REQUESTS) {
      return res.status(429).json({
        error: 'Too many requests',
        message: 'Rate limit exceeded. Please try again later.',
        retryAfter: Math.ceil((record.firstRequest + WINDOW_MS - now) / 1000)
      });
    }
  }

  next();
});

// Security headers
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Prevent MIME type sniffing
  res.setHeader('Content-Type', 'application/json');

  next();
});

// Parse JSON with size limits to prevent abuse
app.use(express.json({
  limit: '10kb'
}));

// Input validation middleware
const validateIdParam = (req, res, next) => {
  const { id } = req.params;

  if (id !== undefined) {
    // Use regex to ensure ID contains only digits
    if (!/^[0-9]+$/.test(id)) {
      return res.status(400).json({
        error: 'Invalid ID format',
        message: 'ID must contain only digits'
      });
    }

    const parsedId = parseInt(id, 10);

    // Validate ID is a positive integer within reasonable bounds
    if (parsedId <= 0 || parsedId > 1000000) {
      return res.status(400).json({
        error: 'Invalid ID value',
        message: 'ID must be a positive integer within a reasonable range'
      });
    }

    // Store validated ID in request object
    req.validated = req.validated || {};
    req.validated.id = parsedId;
  }

  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Service is currently unavailable'
    });
  }
});

// Users endpoint
app.get('/users', validateIdParam, (req, res) => {
  try {
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // If ID is specified in params, return specific user
    if (req.validated && req.validated.id) {
      const user = mockUsers.find(u => u.id === req.validated.id);
      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          message: `User with ID ${req.validated.id} does not exist`
        });
      }
      return res.json(user);
    }

    // Handle query parameters for filtering/searching
    const { name, email } = req.query;

    let filteredUsers = mockUsers;

    // Filter by name if provided
    if (name) {
      // Sanitize input - remove any non-alphanumeric/whitespace characters
      const cleanName = name.toString().replace(/[^a-zA-Z0-9\s]/g, '');
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(cleanName.toLowerCase())
      );
    }

    // Filter by email if provided
    if (email) {
      // Sanitize input - remove any characters that aren't allowed in emails
      const cleanEmail = email.toString().replace(/[^a-zA-Z0-9@._-]/g, '');
      filteredUsers = filteredUsers.filter(user => 
        user.email.toLowerCase().includes(cleanEmail.toLowerCase())
      );
    }

    res.json(filteredUsers);
