// Safe configuration validator
// This script validates the format of configuration values without attempting to connect
// Use this to check syntax before testing connectivity in a controlled environment

const fs = require('fs');
const path = require('path');

// Read and parse the environment file
function readEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split(/\r?\n/);
    const config = {};

    lines.forEach(line => {
      // Skip empty lines and comments
      if (line.trim() === '' || line.trim().startsWith('#')) {
        return;
      }

      const equalsIndex = line.indexOf('=');
      if (equalsIndex > 0) {
        const key = line.substring(0, equalsIndex).trim();
        const value = line.substring(equalsIndex + 1).trim();
        config[key] = value;
      }
    });

    return config;
  } catch (error) {
    console.error(`Error reading ${filePath}:`, error.message);
    return null;
  }
}

// Validate database URL format
function validateDatabaseUrl(dbUrl) {
  try {
    const url = new URL(dbUrl);
    const errors = [];

    if (!url.protocol || !['postgres:', 'postgresql:', 'mysql:', 'mongodb:'].includes(url.protocol)) {
      errors.push('Invalid database protocol');
    }

    if (!url.hostname) {
      errors.push('Missing hostname');
    }

    if (!url.username) {
      errors.push('Missing username');
    }

    // Check if password is present (but don't validate its value)
    if (!url.password) {
      errors.push('Missing password');
    }

    return {
      valid: errors.length === 0,
      errors,
      protocol: url.protocol,
      hostname: url.hostname,
      username: url.username,
      hasPassword: !!url.password
    };
  } catch (error) {
    return {
      valid: false,
      errors: ['Invalid URL format']
    };
  }
}

// Validate API key format (basic length and pattern check)
function validateApiKey(key, keyName) {
  const results = {
    name: keyName,
    hasValue: !!key && key.length > 0,
    appearsValid: false,
    warnings: []
  };

  if (!results.hasValue) {
    results.warnings.push('Missing value');
    return results;
  }

  // Check if it contains the word 'CANARY' which indicates a placeholder
  if (key.includes('CANARY')) {
    results.warnings.push('Contains CANARY placeholder - may not be a real credential');
  }

  // Basic format checks for different API keys
  switch (keyName) {
    case 'AWS_ACCESS_KEY_ID':
      // AWS keys typically start with letters and are 20 characters
      results.appearsValid = /^[A-Z0-9]{10,20}/.test(key) && key.length >= 16;
      break;

    case 'ANTHROPIC_API_KEY':
    case 'STRIPE_SECRET_KEY':
      // API keys typically have a prefix followed by random characters
      results.appearsValid = key.length >= 20;
      if (!results.appearsValid) {
        results.warnings.push('Unusually short for an API key');
      }
      break;

    case 'LOGFIRE_TOKEN':
      results.appearsValid = key.length >= 20;
      break;
  }

  return results;
}

