      console.log(`  Host: ${dbValidation.hostname}`);
      console.log(`  Username: ${dbValidation.username}`);
      console.log(`  Has password: ${dbValidation.hasPassword ? 'yes' : 'no'}\n`);
    } else {
      console.log('✗ DATABASE_URL format is invalid');
      dbValidation.errors.forEach(error => {
        console.log(`  - ${error}`);
      });
      console.log('');
    }
  }

  // Validate API keys
  const apiKeyFields = [
