const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, query } = require('express-validator');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true
  }
}));

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'https://yourdomain.com',
  optionsSuccessStatus: 200
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

app.use(limiter);

// Body parser with size limits
app.use(express.json({
  limit: '10kb'
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Input validation middleware for users endpoint
const validateUserQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),

  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a positive integer'),

  query('sort')
    .optional()
    .isIn(['name', 'email', 'id'])
    .withMessage('Sort field must be name, email, or id')
];

app.get('/health', [
  rateLimit({
    windowMs: 1 * 60 * 1000, // 1 minute
    max: 60, // 60 requests per minute for health checks
    message: 'Health check rate limit exceeded'
  })
], (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

app.get('/users', validateUserQuery, (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      messages: errors.array() 
    });
  }

  // Sample data
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Process query parameters
  let filteredUsers = [...users];

  // Apply limit if specified
  if (req.query.limit) {
    const limit = parseInt(req.query.limit);
    filteredUsers = filteredUsers.slice(0, limit);
  }

  // Apply offset if specified
  if (req.query.offset) {
    const offset = parseInt(req.query.offset);
    filteredUsers = filteredUsers.slice(offset);
  }

  // Apply sorting if specified
  if (req.query.sort) {
    filteredUsers.sort((a, b) => {
      if (a[req.query.sort] < b[req.query.sort]) return -1;
      if (a[req.query.sort] > b[req.query.sort]) return 1;
      return 0;
    });
  }

  res.json(filteredUsers);
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Handle validation errors from express-validator
  if (err.array) {
    return res.status(400).json({
      error: 'Validation failed',
      messages: err.array()
    });
  }

  // Handle JSON parsing errors
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON format'
    });
  }

  // Default error response
  res.status(500).json({
    error: 'Internal server error'
  });
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

