const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const app = express();

// Security middleware
app.use(helmet());
app.use(helmet.hidePoweredBy());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    code: 'RATE_LIMIT_EXCEEDED'
  }
});
app.use(limiter);

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true
}));

// Parse JSON with size limit
app.use(express.json({
  limit: '10kb',
  verify: (req, res, buf) => {
    req.rawBody = buf;
  }
}));

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Remove any potentially dangerous characters from query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        // Basic XSS protection
        req.query[key] = req.query[key]
          .replace(/<script.*?>.*?<\/script>/gi, '')
          .replace(/javascript:/gi, '')
          .replace(/on\w+=/gi, '')
          .trim();
      }
    });
  }
  next();
};
app.use(sanitizeInput);

// Health check with better error handling
app.get('/health', (req, res) => {
  try {
    // Validate request
    if (req.query && Object.keys(req.query).length > 5) {
      return res.status(400).json({
        error: 'Too many query parameters',
        code: 'INVALID_INPUT'
      });
    }

    // Add basic authentication check if needed
    const authHeader = req.get('Authorization');
    if (process.env.REQUIRE_HEALTH_AUTH && authHeader !== `Bearer ${process.env.HEALTH_CHECK_TOKEN}`) {
      return res.status(401).json({
        error: 'Unauthorized',
        code: 'UNAUTHORIZED'
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      nodeEnv: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Health check failed',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Users endpoint with validation and filtering
app.get('/users', (req, res) => {
  try {
    // Input validation
    const { limit, offset, search } = req.query;

    // Validate query parameters
    if (limit && (isNaN(parseInt(limit)) || parseInt(limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        code: 'INVALID_INPUT'
      });
    }

    if (offset && isNaN(parseInt(offset))) {
      return res.status(400).json({
        error: 'Invalid offset parameter',
        code: 'INVALID_INPUT'
      });
    }

    // Mock data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Search filtering (with XSS protection)
    if (search && typeof search === 'string') {
      const searchTerm = search.trim().toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) || 
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Pagination
    const limitNum = limit ? parseInt(limit) : 10;
    const offsetNum = offset ? parseInt(offset) : 0;

    const paginatedUsers = users.slice(offsetNum, offsetNum + limitNum);

    res.json({
      data: paginatedUsers,
      total: users.length,
      limit: limitNum,
      offset: offsetNum,
      hasMore: offsetNum + limitNum < users.length
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Failed to retrieve users',
      code: 'INTERNAL_ERROR'
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`,
    code: 'NOT_FOUND'
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Handle specific error types
  if (error.name === 'ValidationError') {
    return res.status(400).json({
      error: error.message,
      code: 'VALIDATION_ERROR'
    });
  }

  if (error.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Authentication required',
      code: 'UNAUTHORIZED'
    });
  }

  // Generic error
  res.status(500).json({
    error: 'Internal server error',
    code: 'INTERNAL_ERROR'
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, closing server...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

