const express = require('express');
const app = express();

// Security middleware - Security best practices
// Set security HTTP headers
app.use((req, res, next) => {
  // Basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Limit request size to prevent payload attacks
  if (req.method === 'POST' || req.method === 'PUT' || req.method === 'PATCH') {
    req.on('data', (chunk) => {
      if (chunk.length > 100000) { // 100kb limit
        res.status(413).json({ error: 'Payload too large' });
        req.destroy();
      }
    });
  }

  next();
});

// Parse JSON with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} ${req.method} ${req.path} ${req.ip}`);
  next();
});

// Rate limiting simulation (simple in-memory)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 60000; // 1 minute
const MAX_REQUESTS = 100; // max requests per window

app.use((req, res, next) => {
  const clientIP = req.ip;
  const now = Date.now();

  // Clean old entries
  if (requestCounts.size > 1000) {
    // Simple cleanup if too many entries
    const cutoff = now - RATE_LIMIT_WINDOW * 2;
    for (const [ip, data] of requestCounts) {
      if (data.timestamp < cutoff) {
        requestCounts.delete(ip);
      }
    }
  }

  const clientData = requestCounts.get(clientIP) || { count: 0, timestamp: now };

  // Reset counter if outside window
  if (now - clientData.timestamp > RATE_LIMIT_WINDOW) {
    clientData.count = 0;
    clientData.timestamp = now;
  }

  clientData.count++;
  requestCounts.set(clientIP, clientData);

  // Check limit
  if (clientData.count > MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Rate limit exceeded. Please try again later.',
      retryAfter: RATE_LIMIT_WINDOW - (now - clientData.timestamp)
    });
  }

  next();
});

// Input sanitization function
function sanitizeInput(input) {
  if (typeof input !== 'string') return input;
  return input.replace(/[<>"'&;]/g, (match) => {
    // Simple HTML escaping
    const escapeMap = {
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#x27;',
      '&': '&amp;',
      ';': ''
    };
    return escapeMap[match];
  });
}

// Enhanced health check with input validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters
    const verbose = req.query.verbose ? req.query.verbose.toString().toLowerCase() === 'true' : false;

    const response = {
      status: 'ok', 
      timestamp: new Date().toISOString()
    };

    if (verbose) {
      response.info = {
        uptime: process.uptime(),
        memory: process.memoryUsage(),
        nodeVersion: process.version
      };
    }

    res.json(response);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// Users endpoint with input validation and pagination
app.get('/users', (req, res) => {
  try {
    // Mock data
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Input validation and sanitization
    const page = req.query.page ? parseInt(sanitizeInput(req.query.page.toString())) : 1;
    const limit = req.query.limit ? parseInt(sanitizeInput(req.query.limit.toString())) : 10;
    const search = req.query.search ? sanitizeInput(req.query.search.toString()) : '';

    // Validate and sanitize inputs
    if (isNaN(page) || page < 1) {
      return res.status(400).json({
        error: 'Invalid page parameter',
        message: 'Page must be a positive integer'
      });
    }

    if (isNaN(limit) || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid limit parameter',
        message: 'Limit must be between 1 and 100'
      });
    }

    // Filter users if search query is provided
    let filteredUsers = mockUsers;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = mockUsers.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Response with pagination metadata
    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        totalPages: Math.ceil(filteredUsers.length / limit),
        totalUsers: filteredUsers.length,
        hasNext: endIndex < filteredUsers.length,
        hasPrev: startIndex > 0
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `The route ${req.method} ${req.path} does not exist`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Handle common error types
  if (error.name === 'SyntaxError' && error.status === 400) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid JSON in request body'
    });
  }

  res.status(500).json({
    error: 'Internal server error',
    message: 'An unexpected error occurred'
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Security features enabled:`);
  console.log(`- Security HTTP headers`);
  console.log(`- Rate limiting (max ${MAX_REQUESTS}/minute)`);
  console.log(`- Input validation and sanitization`);
  console.log(`- Request size limits`);
  console.log(`- Comprehensive error handling`);
});

